package com.pixie.android.audio

import android.content.Context
import android.media.AudioAttributes
import android.media.SoundPool
import android.util.Log
import com.pixie.engine.core.ports.AudioEvent
import com.pixie.engine.core.ports.AudioPort
import java.io.File
import java.util.concurrent.ConcurrentHashMap

/**
 * Standardized Android SoundPool audio adapter for Pixie Engine.
 *
 * Provides responsive ultra-low-latency audio playback for retro arcade sound effects
 * powered by procedural waveforms generated by [RetroAudioSynthesizer].
 */
class AndroidSoundPoolAudioAdapter(val context: Context) : AudioPort {

    private val soundPool: SoundPool = SoundPool.Builder()
        .setMaxStreams(16)
        .setAudioAttributes(
            AudioAttributes.Builder()
                .setUsage(AudioAttributes.USAGE_GAME)
                .setContentType(AudioAttributes.CONTENT_TYPE_SONIFICATION)
                .build()
        )
        .build()

    private val soundMap = ConcurrentHashMap<AudioEvent, Int>()
    private val loadedSoundIds = ConcurrentHashMap.newKeySet<Int>()

    override var isMuted: Boolean = false
    var masterVolume: Float = 0.85f

    init {
        soundPool.setOnLoadCompleteListener { _, sampleId, status ->
            if (status == 0) {
                loadedSoundIds.add(sampleId)
            } else {
                Log.w("PixieAudio", "Failed to load sample ID: $sampleId status: $status")
            }
        }

        loadSounds()
    }

    private fun loadSounds() {
        try {
            val audioDir = File(context.cacheDir, "pixie_retro_sounds")
            val soundFiles = RetroAudioSynthesizer.generateAllSounds(audioDir)

            for ((event, file) in soundFiles) {
                val soundId = soundPool.load(file.absolutePath, 1)
                soundMap[event] = soundId
            }
        } catch (e: Exception) {
            Log.e("PixieAudio", "Error initializing procedural retro sounds", e)
        }
    }

    override fun playSound(event: AudioEvent) {
        if (isMuted) return

        val soundId = soundMap[event] ?: return

        // Pitch variations give natural arcade vitality
        val pitch = when (event) {
            AudioEvent.JUMP -> 1.0f + (Math.random().toFloat() * 0.1f - 0.05f)
            AudioEvent.DUCK -> 0.95f
            AudioEvent.COLLECT -> 1.0f + (Math.random().toFloat() * 0.08f)
            AudioEvent.HIT -> 0.9f + (Math.random().toFloat() * 0.2f)
            AudioEvent.SCORE_MILESTONE -> 1.0f
            AudioEvent.GAME_OVER -> 1.0f
            AudioEvent.BUTTON_CLICK -> 1.0f
            AudioEvent.DAY_NIGHT_SHIFT -> 1.0f
            AudioEvent.FIRE_PRIMARY -> 0.98f + (Math.random().toFloat() * 0.08f)
            AudioEvent.FIRE_MISSILE -> 0.95f + (Math.random().toFloat() * 0.1f)
            AudioEvent.EXPLOSION_SMALL -> 0.95f + (Math.random().toFloat() * 0.15f)
            AudioEvent.EXPLOSION_LARGE -> 0.90f + (Math.random().toFloat() * 0.15f)
            AudioEvent.SHIELD_HIT -> 1.0f + (Math.random().toFloat() * 0.1f)
            AudioEvent.POWERUP_PICKUP -> 1.0f
        }

        val volume = when (event) {
            AudioEvent.FIRE_PRIMARY -> masterVolume * 0.65f // softer to prevent ear fatigue during rapid fire
            AudioEvent.FIRE_MISSILE -> masterVolume * 0.85f
            AudioEvent.EXPLOSION_SMALL -> masterVolume * 0.80f
            AudioEvent.EXPLOSION_LARGE -> masterVolume * 1.0f
            AudioEvent.BUTTON_CLICK -> masterVolume * 0.5f
            else -> masterVolume
        }

        // Even if load listener hasn't finished (first few ms), soundPool.play handles gracefully
        soundPool.play(soundId, volume, volume, 1, 0, pitch)
    }

    fun release() {
        soundPool.release()
    }
}
